import fs from "node:fs";
import path from "node:path";
import { UPLOAD_DIR } from "@/lib/db";

export async function GET(_req: Request, ctx: RouteContext<"/api/uploads/[id]">) {
  const { id } = await ctx.params;
  // IDs are generated by us as hex; anything else could be a path traversal attempt.
  if (!/^[a-f0-9]+$/.test(id)) return new Response("Not found", { status: 404 });
  const file = path.join(UPLOAD_DIR, `${id}.jpg`);
  if (!fs.existsSync(file)) return new Response("Not found", { status: 404 });
  return new Response(fs.readFileSync(file), { headers: { "Content-Type": "image/jpeg", "Cache-Control": "public, max-age=86400, immutable", "X-Content-Type-Options": "nosniff" } });
}
